package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

const (
	appName    = "sd"
	appVersion = "1.0.0"
	appAbout   = "An intuitive find & replace CLI"
)

type options struct {
	preview         bool
	fixedStrings    bool
	maxReplacements int
	flags           string
	find            string
	replaceWith     string
	files           []string
}

func main() {
	binName := filepath.Base(os.Args[0])

	opts, action, err := parseArgs(os.Args[1:], binName)
	if err != nil {
		fmt.Fprint(os.Stderr, err.render(binName))
		os.Exit(2)
	}

	switch action {
	case actionShortHelp:
		fmt.Print(shortHelp(binName))
		return
	case actionLongHelp:
		fmt.Print(longHelp(binName))
		return
	case actionVersion:
		fmt.Printf("%s %s\n", appName, appVersion)
		return
	}

	matcher, err := compileMatcher(opts.find, opts.fixedStrings, opts.flags)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid regex %v\n", err)
		os.Exit(1)
	}

	if len(opts.files) == 0 {
		input, err := io.ReadAll(os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %v\n", err)
			os.Exit(1)
		}

		output := applyReplacements(matcher, input, opts.replaceWith, opts.fixedStrings, opts.maxReplacements)
		if _, err := os.Stdout.Write(output); err != nil {
			fmt.Fprintf(os.Stderr, "error: %v\n", err)
			os.Exit(1)
		}
		return
	}

	for _, path := range opts.files {
		if _, err := os.Stat(path); os.IsNotExist(err) {
			fmt.Fprintf(os.Stderr, "error: invalid path: %s\n", path)
			os.Exit(1)
		}
	}

	type fileData struct {
		path    string
		content []byte
	}

	files := make([]fileData, 0, len(opts.files))
	for _, path := range opts.files {
		content, err := os.ReadFile(path)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %v\n", err)
			os.Exit(1)
		}
		files = append(files, fileData{path: path, content: content})
	}

	outputs := make([]fileData, 0, len(files))
	for _, file := range files {
		outputs = append(outputs, fileData{
			path:    file.path,
			content: applyReplacements(matcher, file.content, opts.replaceWith, opts.fixedStrings, opts.maxReplacements),
		})
	}

	if opts.preview {
		if len(outputs) == 1 {
			if _, err := os.Stdout.Write(outputs[0].content); err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
			return
		}

		for _, output := range outputs {
			if _, err := fmt.Fprintf(os.Stdout, "----- FILE %s -----\n", output.path); err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
			if _, err := os.Stdout.Write(output.content); err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
		}
		return
	}

	for _, output := range outputs {
		if err := os.WriteFile(output.path, output.content, 0o666); err != nil {
			fmt.Fprintf(os.Stderr, "error: %v\n", err)
			os.Exit(1)
		}
	}
}

type action int

const (
	actionRun action = iota
	actionShortHelp
	actionLongHelp
	actionVersion
)

type cliError struct {
	message string
	usage   string
}

func (e cliError) render(binName string) string {
	if e.usage == "" {
		return fmt.Sprintf("error: %s\n\nFor more information, try '--help'.\n", e.message)
	}

	return fmt.Sprintf(
		"error: %s\n\nUsage: %s %s\n\nFor more information, try '--help'.\n",
		e.message,
		binName,
		e.usage,
	)
}

func parseArgs(args []string, binName string) (options, action, *cliError) {
	var opts options

	var previewSet bool
	var fixedStringsSet bool
	var maxReplacementsSet bool
	var flagsSet bool
	var positional []string
	parsingFlags := true

	for i := 0; i < len(args); i++ {
		arg := args[i]

		if parsingFlags {
			switch arg {
			case "--":
				parsingFlags = false
				continue
			case "--help":
				return options{}, actionLongHelp, nil
			case "-h":
				return options{}, actionShortHelp, nil
			case "--version", "-V":
				return options{}, actionVersion, nil
			}
		}

		if parsingFlags && strings.HasPrefix(arg, "--") && arg != "--" {
			name, value, hasValue := splitLong(arg)

			switch name {
			case "--preview":
				if hasValue {
					return options{}, actionRun, &cliError{
						message: fmt.Sprintf("unexpected value '%s' for '--preview' found; no more were expected", value),
						usage:   "--preview <FIND> <REPLACE_WITH> [FILES]...",
					}
				}
				if previewSet {
					return options{}, actionRun, repeatedOptionError("--preview")
				}
				previewSet = true
				opts.preview = true
			case "--fixed-strings":
				if hasValue {
					return options{}, actionRun, &cliError{
						message: fmt.Sprintf("unexpected value '%s' for '--fixed-strings' found; no more were expected", value),
						usage:   "--fixed-strings <FIND> <REPLACE_WITH> [FILES]...",
					}
				}
				if fixedStringsSet {
					return options{}, actionRun, repeatedOptionError("--fixed-strings")
				}
				fixedStringsSet = true
				opts.fixedStrings = true
			case "--max-replacements":
				if maxReplacementsSet {
					return options{}, actionRun, repeatedOptionError("--max-replacements <LIMIT>")
				}
				if !hasValue {
					if i+1 >= len(args) || looksLikeOption(args[i+1]) {
						return options{}, actionRun, missingValueError("--max-replacements <LIMIT>")
					}
					i++
					value = args[i]
				}
				parsed, ok := parseMaxReplacements(value)
				if !ok {
					return options{}, actionRun, invalidValueError("--max-replacements <LIMIT>", value)
				}
				maxReplacementsSet = true
				opts.maxReplacements = parsed
			case "--flags":
				if flagsSet {
					return options{}, actionRun, repeatedOptionError("--flags <FLAGS>")
				}
				if !hasValue {
					if i+1 >= len(args) || looksLikeOption(args[i+1]) {
						return options{}, actionRun, missingValueError("--flags <FLAGS>")
					}
					i++
					value = args[i]
				}
				flagsSet = true
				opts.flags = value
			default:
				return options{}, actionRun, unexpectedArgError(arg)
			}
			continue
		}

		if parsingFlags && strings.HasPrefix(arg, "-") && arg != "-" {
			cluster := arg[1:]
			for j := 0; j < len(cluster); j++ {
				switch cluster[j] {
				case 'h':
					return options{}, actionShortHelp, nil
				case 'V':
					return options{}, actionVersion, nil
				case 'p':
					if previewSet {
						return options{}, actionRun, repeatedOptionError("--preview")
					}
					previewSet = true
					opts.preview = true
				case 'F':
					if fixedStringsSet {
						return options{}, actionRun, repeatedOptionError("--fixed-strings")
					}
					fixedStringsSet = true
					opts.fixedStrings = true
				case 'n':
					if maxReplacementsSet {
						return options{}, actionRun, repeatedOptionError("--max-replacements <LIMIT>")
					}
					value := cluster[j+1:]
					if value == "" {
						if i+1 >= len(args) {
							return options{}, actionRun, missingValueError("--max-replacements <LIMIT>")
						}
						if looksLikeOption(args[i+1]) {
							return options{}, actionRun, unexpectedArgError(args[i+1])
						}
						i++
						value = args[i]
					}
					parsed, ok := parseMaxReplacements(value)
					if !ok {
						return options{}, actionRun, invalidValueError("--max-replacements <LIMIT>", value)
					}
					maxReplacementsSet = true
					opts.maxReplacements = parsed
					j = len(cluster)
				case 'f':
					if flagsSet {
						return options{}, actionRun, repeatedOptionError("--flags <FLAGS>")
					}
					value := cluster[j+1:]
					if value == "" {
						if i+1 >= len(args) {
							return options{}, actionRun, missingValueError("--flags <FLAGS>")
						}
						if looksLikeOption(args[i+1]) {
							return options{}, actionRun, unexpectedArgError(args[i+1])
						}
						i++
						value = args[i]
					}
					flagsSet = true
					opts.flags = value
					j = len(cluster)
				default:
					return options{}, actionRun, unexpectedArgError("-"+string(cluster[j]))
				}
			}
			continue
		}

		positional = append(positional, arg)
	}

	if len(positional) < 2 {

	if len(positional) < 2 {
		return options{}, actionRun, missingArgumentsError(positional)
	}

	opts.find = positional[0]
	opts.replaceWith = positional[1]
	if len(positional) > 2 {
		opts.files = append(opts.files, positional[2:]...)
	}

	return opts, actionRun, nil
}

func splitLong(arg string) (string, string, bool) {
	name, value, ok := strings.Cut(arg, "=")
	return name, value, ok
}

func looksLikeOption(arg string) bool {
	return strings.HasPrefix(arg, "-") && arg != "-"
}

func repeatedOptionError(name string) *cliError {
	return &cliError{
		message: fmt.Sprintf("the argument '%s' cannot be used multiple times", name),
		usage:   "[OPTIONS] <FIND> <REPLACE_WITH> [FILES]...",
	}
}

func missingValueError(name string) *cliError {
	return &cliError{
		message: fmt.Sprintf("a value is required for '%s' but none was supplied", name),
	}
}

func invalidValueError(name, value string) *cliError {
	return &cliError{
		message: fmt.Sprintf("invalid value '%s' for '%s': invalid digit found in string", value, name),
	}
}

func unexpectedArgError(arg string) *cliError {
	return &cliError{
		message: fmt.Sprintf("unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'", arg, arg, arg),
		usage:   "[OPTIONS] <FIND> <REPLACE_WITH> [FILES]...",
	}
}

func missingArgumentsError(positional []string) *cliError {
	missing := []string{}
	if len(positional) == 0 {
		missing = append(missing, "  <FIND>")
	}
	if len(positional) <= 1 {
		missing = append(missing, "  <REPLACE_WITH>")
	}

	return &cliError{
		message: fmt.Sprintf(
			"the following required arguments were not provided:\n%s",
			strings.Join(missing, "\n"),
		),
		usage: "<FIND> <REPLACE_WITH> [FILES]...",
	}
}

func parseMaxReplacements(value string) (int, bool) {
	if value == "" {
		return 0, false
	}
	for _, ch := range value {
		if ch < '0' || ch > '9' {
			return 0, false
		}
	}

	parsed, err := strconv.ParseUint(value, 10, strconv.IntSize)
	if err != nil {
		return 0, false
	}

	return int(parsed), true
}

func compileMatcher(find string, fixedStrings bool, flags string) (*regexp.Regexp, error) {
	var builder strings.Builder

	if !strings.ContainsRune(flags, 'e') {
		builder.WriteString("(?m)")
	}

	for _, flag := range flags {
		switch flag {
		case 'c':
			builder.WriteString("(?-i)")
		case 'i':
			builder.WriteString("(?i)")
		case 's':
			builder.WriteString("(?s)")
		}
	}

	pattern := find
	if fixedStrings {
		pattern = regexp.QuoteMeta(pattern)
	}
	if strings.ContainsRune(flags, 'w') {
		pattern = `\b(?:` + pattern + `)\b`
	}

	builder.WriteString(pattern)
	return regexp.Compile(builder.String())
}

func applyReplacements(re *regexp.Regexp, input []byte, replaceWith string, fixedStrings bool, maxReplacements int) []byte {
	matches := re.FindAllSubmatchIndex(input, replacementLimit(maxReplacements))
	if len(matches) == 0 {
		return append([]byte(nil), input...)
	}

	names := re.SubexpNames()
	output := make([]byte, 0, len(input))
	last := 0

	for _, match := range matches {
		start, end := match[0], match[1]
		output = append(output, input[last:start]...)
		if fixedStrings {
			output = append(output, replaceWith...)
		} else {
			output = appendExpandedReplacement(output, replaceWith, input, match, names)
		}
		last = end
	}

	output = append(output, input[last:]...)
	return output
}

func replacementLimit(maxReplacements int) int {
	if maxReplacements == 0 {
		return -1
	}
	return maxReplacements
}

func appendExpandedReplacement(dst []byte, template string, src []byte, match []int, names []string) []byte {
	for i := 0; i < len(template); i++ {
		if template[i] != '$' {
			dst = append(dst, template[i])
			continue
		}

		if i+1 >= len(template) {
			dst = append(dst, '$')
			continue
		}

		next := template[i+1]
		if next == '$' {
			dst = append(dst, '$')
			i++
			continue
		}

		if next == '{' {
			end := strings.IndexByte(template[i+2:], '}')
			if end < 0 {
				dst = append(dst, '$')
				continue
			}

			name := template[i+2 : i+2+end]
			dst = appendCapture(dst, name, src, match, names)
			i += end + 2
			continue
		}

		if isCaptureChar(next) {
			j := i + 1
			for j < len(template) && isCaptureChar(template[j]) {
				j++
			}
			name := template[i+1 : j]
			dst = appendCapture(dst, name, src, match, names)
			i = j - 1
			continue
		}

		dst = append(dst, '$')
	}

	return dst
}

func isCaptureChar(ch byte) bool {
	return ch == '_' || (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')
}

func appendCapture(dst []byte, name string, src []byte, match []int, names []string) []byte {
	if name == "" {
		return dst
	}

	if isAllDigits(name) {
		index, err := strconv.Atoi(name)
		if err != nil {
			return dst
		}
		return appendMatchByIndex(dst, index, src, match)
	}

	for idx, candidate := range names {
		if candidate == name {
			return appendMatchByIndex(dst, idx, src, match)
		}
	}

	return dst
}

func isAllDigits(value string) bool {
	for _, ch := range value {
		if ch < '0' || ch > '9' {
			return false
		}
	}
	return value != ""
}

func appendMatchByIndex(dst []byte, index int, src []byte, match []int) []byte {
	slot := index * 2
	if slot+1 >= len(match) {
		return dst
	}

	start, end := match[slot], match[slot+1]
	if start < 0 || end < 0 {
		return dst
	}

	return append(dst, src[start:end]...)
}

func shortHelp(binName string) string {
	return fmt.Sprintf(`%s v%s
%s

Usage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...

Arguments:
  <FIND>          The regexp or string (if using `+"`-F`"+`) to search for
  <REPLACE_WITH>  What to replace each match with. Unless in string mode, you may use captured
                  values like $1, $2, etc
  [FILES]...      The path to file(s). This is optional - sd can also read from STDIN

Options:
  -p, --preview                   Display changes in a human reviewable format (the specifics of the
                                  format are likely to change in the future)
  -F, --fixed-strings             Treat FIND and REPLACE_WITH args as literal strings
  -n, --max-replacements <LIMIT>  Limit the number of replacements that can occur per file. 0
                                  indicates unlimited replacements [default: 0]
  -f, --flags <FLAGS>             Regex flags. May be combined (like `+"`-f mc`"+`).
  -h, --help                      Print help (see more with `+"`--help`"+`)
  -V, --version                   Print version
`, appName, appVersion, appAbout, binName)
}

func longHelp(binName string) string {
	return fmt.Sprintf(`%s v%s
%s

Usage: %s [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...

Arguments:
  <FIND>
          The regexp or string (if using `+"`-F`"+`) to search for

  <REPLACE_WITH>
          What to replace each match with. Unless in string mode, you may use captured values like
          $1, $2, etc

  [FILES]...
          The path to file(s). This is optional - sd can also read from STDIN.

          Note: sd modifies files in-place by default. See documentation for examples.

Options:
  -p, --preview
          Display changes in a human reviewable format (the specifics of the format are likely to
          change in the future)

  -F, --fixed-strings
          Treat FIND and REPLACE_WITH args as literal strings

  -n, --max-replacements <LIMIT>
          Limit the number of replacements that can occur per file. 0 indicates unlimited
          replacements

          [default: 0]

  -f, --flags <FLAGS>
          Regex flags. May be combined (like `+"`-f mc`"+`).

          c - case-sensitive

          e - disable multi-line matching

          i - case-insensitive

          m - multi-line matching

          s - make `.` match newlines

          w - match full words only

  -h, --help
          Print help (see a summary with `+"`-h`"+`)

  -V, --version
          Print version
`, appName, appVersion, appAbout, binName)
}

